package school.chacademia.wildlife;
import org.junit.jupiter.api.Test;import org.bukkit.*;import org.bukkit.entity.Player;import org.bukkit.configuration.file.YamlConfiguration;import java.util.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class WildSpawnerTest {
 @Test void defaultsMatchApprovedBudgetAndExistingHabitatRarityFallsBack(){var warnings=new ArrayList<String>();var s=WildSpawner.Settings.parse(null,warnings);assertTrue(s.enabled());assertEquals(100,s.periodTicks());assertEquals(3,s.attemptsPerPlayer());assertEquals(40,s.maxAttemptsPerTick());assertEquals(Map.of("1",4.5,"2",1.8,"3",.4,"boss",.06),s.rarityWeights());var y=new YamlConfiguration();y.set("biomes",List.of("minecraft:plains"));y.set("group-min",1);y.set("group-max",2);y.set("cap",4);y.set("min-y",-64);y.set("max-y",320);assertEquals("3",Habitat.parse("test",y,warnings,Map.of("test","3")).rarity());y.set("rarity","2");y.set("name","검증 종");y.set("weight",.7);var h=Habitat.parse("test",y,warnings,Map.of("test","3"));assertEquals("2",h.rarity());assertEquals("검증 종",h.name());assertEquals(.7,h.weight());}
 @Test void unloadedChunksNeverLoadOrReadBlocksAndTickBudgetIsGlobal()throws Exception{exercise(false);}
 @Test void fullChunksRejectBeforeHeightOrBlockReadsAndCountOncePerAttempt()throws Exception{exercise(true);}
 private void exercise(boolean full)throws Exception{var plugin=mock(WildlifePlugin.class);var world=mock(World.class);var chunk=mock(Chunk.class);when(plugin.spawnWorlds()).thenReturn(Set.of("world"));when(plugin.playerMinDistance()).thenReturn(24d);when(plugin.playerMaxDistance()).thenReturn(80d);when(world.isChunkLoaded(anyInt(),anyInt())).thenReturn(full);when(world.getChunkAt(anyInt(),anyInt())).thenReturn(chunk);when(plugin.chunkFull(chunk)).thenReturn(true);var players=new ArrayList<Player>();for(int i=0;i<50;i++){var player=mock(Player.class);when(player.getGameMode()).thenReturn(GameMode.SURVIVAL);when(player.getEntityId()).thenReturn(1);when(player.getWorld()).thenReturn(world);when(player.getLocation()).thenReturn(new Location(world,0,64,0));players.add(player);}when(world.getPlayers()).thenReturn(players);var spawner=new WildSpawner(plugin);var field=WildSpawner.class.getDeclaredField("settings");field.setAccessible(true);field.set(spawner,WildSpawner.Settings.parse(null,new ArrayList<>()));var tick=WildSpawner.class.getDeclaredMethod("tick");tick.setAccessible(true);try(var b=mockStatic(Bukkit.class)){b.when(()->Bukkit.getWorld("world")).thenReturn(world);tick.invoke(spawner);tick.invoke(spawner);}verify(world,times(40)).isChunkLoaded(anyInt(),anyInt());verify(world,full?times(40):never()).getChunkAt(anyInt(),anyInt());verify(plugin,full?times(40):never()).chunkFull(chunk);verify(world,never()).getHighestBlockYAt(anyInt(),anyInt(),any(HeightMap.class));verify(world,never()).getBlockAt(anyInt(),anyInt(),anyInt());var count=WildSpawner.class.getDeclaredField("attempts");count.setAccessible(true);assertEquals(40,count.getLong(spawner));}
 @Test void bundledSpeciesGradesCoverAll138()throws Exception{try(var in=getClass().getResourceAsStream("/habitats.yml")){assertNotNull(in);var y=YamlConfiguration.loadConfiguration(new java.io.InputStreamReader(in,java.nio.charset.StandardCharsets.UTF_8)).getConfigurationSection("habitats");assertNotNull(y);assertEquals(138,y.getKeys(false).size());var grades=new HashMap<String,Integer>();for(var id:y.getKeys(false))grades.merge(y.getString(id+".rarity"),1,Integer::sum);assertEquals(Map.of("1",33,"2",45,"3",59,"boss",1),grades);assertEquals("boss",y.getString("glacialcore.rarity"));}}
}
